-- 2026-11-12: Early Support Visits by Caring Companions (her decisions that day; the page, the rates box and Exhibit J are live).
-- Two answers, each added once and updated only when its text differs:
--   K157 (public): what the website chat says about Early Support Visits. Same text as supabase/knowledge/cara-2026-10-27.mjs.
--   OR27 (internal): the same facts for Ask Cara in the Hub, with the office steps. Internal answers never reach the website chat.
-- Nothing else changes. K103 (minimum hours) stays held, as she chose on 2026-11-07.
insert into public.kb_items (id, question, answer, answer_key, source_id, topics, alt_questions, aliases, phrases, status, audience, confidence, conservative, verified_on, verified_by, review_legal, review_clinical, review_marketing, version)
values ('K157', 'What are Early Support Visits?', 'Early Support Visits are for older adults in Springfield who are doing well at home and would like a helping hand around the house and good company now and then. A caregiver comes for a 4-hour visit once a month for $152 a visit, or every other week for $140 a visit. Before visits begin there is a one-time $99 in-home assessment and setup, billed with the first visit. See mo-care.com/early-support-visits or call (417) 234-8494.', 'early_support_visits', 'S9', array['early support','once a month','every other week','occasional']::text[], array['Do you offer occasional visits?','Can someone come once a month?','Can a caregiver come every other week?','Do you do monthly visits?','How much are Early Support Visits?','Can we have a visit now and then?']::text[], array[]::text[], array[]::text[], 'verified', 'public', 95, false, '2026-11-12', 'Samantha 11-12: Early Support Visits decisions', 'na', 'na', 'ok', 1)
on conflict (id) do update set question = excluded.question, answer = excluded.answer, answer_key = excluded.answer_key, source_id = excluded.source_id,
  topics = excluded.topics, alt_questions = excluded.alt_questions, status = excluded.status, verified_on = excluded.verified_on,
  verified_by = excluded.verified_by, version = kb_items.version + (kb_items.answer is distinct from excluded.answer)::int, updated_at = now();

insert into public.kb_items (id, question, answer, source_id, topics, status, audience, verified_on, verified_by, confidence, conservative, review_legal, review_clinical, review_marketing)
values ('OR27', 'Early Support Visits', 'A separate program, not a fourth care level. Springfield only. One 4-hour visit once a month ($152 a visit, $38 an hour) or every other week ($140 a visit, $35 an hour). No weekly option. One-time $99 assessment and setup, billed with the first visit; nothing is paid at the assessment. It is Exhibit J of the Client Care Agreement: on the tablet''s set-up screen tick the enrolling box, pick the schedule and type the regular visit day. Regular care is still 4-hour visits, 8 hours a week. Never promise the same caregiver or an extra visit. Steps are on Payors & Programs, Early Support Visits tab.', 'S10', array['early support','once a month','every other week','exhibit j','occasional']::text[], 'verified', 'internal', '2026-11-12', 'Samantha 11-12: Early Support Visits decisions', 100, false, 'na', 'na', 'na')
on conflict (id) do update set answer = excluded.answer, topics = excluded.topics, status = excluded.status, verified_on = excluded.verified_on, verified_by = excluded.verified_by, updated_at = now();
